import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';import{World}from'../world.js';import{footprintCells,rotateCell,resolveBuildingTarget,doorVector}from'../building-geometry.js';import{findPath}from'../navigation.js';
const raw=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));const w=new World(raw);
test('every furnished room has one architectural outline and a unique registry identity',()=>{const rooms=w.data.scenes.filter(s=>s.household);assert.equal(w.data.buildingRegistry.length,rooms.length);assert.equal(new Set(w.data.buildingRegistry.map(r=>r.id)).size,rooms.length);for(const r of rooms){assert.ok(r.architecture.outline.length,r.key);const cells=new Set(footprintCells(r).map(p=>p.join(',')));for(const o of r.household.furnishings.filter(o=>![16,18].includes(o.furniture)))for(let y=o.footprint.y;y<o.footprint.y+o.footprint.h;y++)for(let x=o.footprint.x;x<o.footprint.x+o.footprint.w;x++)assert.ok(cells.has(x+','+y),r.key+' object inside shell');}});
test('every exterior roof is exactly a rotated uniformly scaled copy of its interior footprint',()=>{let count=0;for(const street of w.data.scenes)for(const p of street.exteriorBuildings||[]){count++;const r=w.scenes.get(p.projection.roomLocation),d=p.projection.door,actual=new Set(p.projection.cells.map(v=>v.join(','))),expected=footprintCells(r).map(([x,y])=>rotateCell([x-d[0],y-d[1]],p.projection.turns).join(','));assert.equal(actual.size,expected.length);assert.ok(expected.every(k=>actual.has(k)));assert.ok(p.projection.scale>0&&Number.isFinite(p.projection.scale));assert.ok(p.projection.bounds.maxX>=p.projection.bounds.minX);assert.equal(resolveBuildingTarget(w.data,street,p.exit).location,r.location);}assert.ok(count>30);});
test('inn, clinic and joiner entrances are reachable from the public square and enter free floor',()=>{const town=w.data.scenes.find(s=>s.key==='town');for(const key of['inn','clinic','carpenter']){const exit=town.objects.find(o=>o.streetService&&o.to===key);assert.ok(exit,key);assert.ok(findPath(town,town.arrive,exit.xy,1).length,key);const r=resolveBuildingTarget(w.data,town,exit);assert.equal(r.floor[exit.arrive[1]][exit.arrive[0]],'.');}});
test('entering and returning uses the same street threshold, including after a save roundtrip',()=>{const town=w.data.scenes.find(s=>s.key==='town');for(const key of['inn','clinic','carpenter']){w.state.mode='field';w.state.scene=town.location;w.state.story.parcel=true;const exit=town.objects.find(o=>o.to===key);w.portal(exit);const room=w.scene;assert.equal(room.key,key);assert.ok(w.walkable(w.state.x,w.state.y));w.restore(w.save());w.state.mode='field';const back=room.doors.find(d=>resolveBuildingTarget(w.data,room,d)?.location===town.location);assert.ok(back);w.portal(back);assert.equal(w.state.scene,town.location);assert.equal(w.state.x,exit.xy[0]+.5);assert.equal(w.state.y,exit.xy[1]+.5);}});
test('interior window bays and ordinary thresholds refer to the same shell, without removing campaign gates',()=>{for(const r of w.data.scenes.filter(s=>s.household)){const outline=new Set(footprintCells(r).map(p=>p.join(',')));for(const d of r.doors){if(d.architecturalKind==='stairs')continue;const [dx,dy]=doorVector(d.wallSide);assert.ok(!outline.has((d.xy[0]+dx)+','+(d.xy[1]+dy)),r.key+' boundary');}}const hatch=w.data.scenes.find(s=>s.key==='town').objects.find(o=>o.to==='workshop');assert.ok(hatch.requires_flags.length);});
